#!/usr/bin/env python3
# ==============================================================================
# Script: extract_sections.py
# Purpose: Extract clean images, section-by-section text, and design specs
#          from absolute-positioned HTML files generated by kio-pdf2html.
# ==============================================================================

import os
import sys
import re
import base64
import html

def extract_sections(html_file, output_dir=None):
    if not os.path.isfile(html_file):
        print(f"[ERROR] File not found: {html_file}", file=sys.stderr)
        sys.exit(1)

    if not output_dir:
        base_name = os.path.splitext(os.path.basename(html_file))[0]
        output_dir = os.path.join(os.path.dirname(os.path.abspath(html_file)), f"{base_name}_extracted")

    images_dir = os.path.join(output_dir, "images")
    os.makedirs(images_dir, exist_ok=True)

    with open(html_file, "r", encoding="utf-8", errors="ignore") as f:
        content = f.read()

    # Extract color tokens
    color_matches = re.findall(r'color:\s*(#[0-9a-fA-F]{3,8}|rgba?\([^)]+\))', content)
    unique_colors = []
    for c in color_matches:
        c_lower = c.lower()
        if c_lower not in unique_colors and c_lower not in ['#000000', '#ffffff', 'transparent']:
            unique_colors.append(c_lower)

    # Extract pages
    pages = re.findall(r'(<div id="page(\d+)-div".*?)(?=<div id="page\d+-div"|</body>|$)', content, re.DOTALL)
    if not pages:
        # Fallback for other pdftohtml id formats
        pages = re.findall(r'(<div id="page(\d+)".*?)(?=<div id="page\d+"|</body>|$)', content, re.DOTALL)

    print(f"[*] Found {len(pages)} pages/sections in {html_file}")

    spec_lines = [
        f"# 🎨 Design Specification & Section Map",
        f"- **Source File**: `{os.path.basename(html_file)}`",
        f"- **Total Sections**: {len(pages)}",
        f"- **Extracted Brand Colors**: {', '.join([f'`{c}`' for c in unique_colors[:8]])}",
        f"",
        f"---",
        f""
    ]

    for p_html, p_num in pages:
        p_idx = int(p_num)
        sec_name = f"section_{p_idx:02d}"
        
        # 1. Extract Background Image
        imgs = re.findall(r'src="data:image/(jpeg|png|webp);base64,([^"]+)"', p_html)
        img_rel_path = "None"
        if imgs:
            ext, b64_data = imgs[0]
            ext = "jpg" if ext == "jpeg" else ext
            img_filename = f"{sec_name}_bg.{ext}"
            img_filepath = os.path.join(images_dir, img_filename)
            try:
                with open(img_filepath, "wb") as img_f:
                    img_f.write(base64.b64decode(b64_data))
                img_rel_path = f"images/{img_filename}"
            except Exception as e:
                print(f"[!] Warning: failed to save image for page {p_num}: {e}")

        # 2. Extract Text Elements & Coordinates
        p_tags = re.findall(r'<p\s+style="([^"]*)"\s+class="([^"]*)">(.*?)</p>', p_html, re.DOTALL)
        
        text_entries = []
        for style_str, cls_name, raw_text in p_tags:
            # Parse top and left
            top_m = re.search(r'top:\s*(\d+)px', style_str)
            left_m = re.search(r'left:\s*(\d+)px', style_str)
            top = int(top_m.group(1)) if top_m else 0
            left = int(left_m.group(1)) if left_m else 0
            
            clean_text = re.sub(r'<[^>]+>', '', raw_text)
            clean_text = clean_text.replace('&#160;', ' ').replace('&nbsp;', ' ')
            clean_text = html.unescape(clean_text).strip()
            
            if clean_text:
                text_entries.append((top, left, clean_text))

        # Sort text entries by vertical position (top to bottom)
        text_entries.sort(key=lambda x: (x[0], x[1]))

        # Group text entries
        spec_lines.append(f"## 📱 Section {p_idx} (Slide {p_idx})")
        spec_lines.append(f"- **Background Asset**: `[{img_rel_path}]({img_rel_path})`")
        spec_lines.append(f"- **Content Blocks** (Top-to-Bottom):")
        
        for top, left, txt in text_entries:
            # Detect buttons/CTAs (all caps or short action verbs)
            if any(w in txt.lower() for w in ['xem', 'nhận', 'đặt', 'liên hệ', 'báo giá', 'chi tiết', 'click', 'book', 'call']) and len(txt) < 40:
                spec_lines.append(f"  - 🔘 **Button / CTA**: `{txt}` (top: {top}px, left: {left}px)")
            elif len(txt) > 80:
                spec_lines.append(f"  - 📝 **Paragraph**: {txt}")
            else:
                spec_lines.append(f"  - 📌 **Heading/Label**: **{txt}**")

        spec_lines.append("")
        spec_lines.append("---")
        spec_lines.append("")

    # Write spec file
    spec_path = os.path.join(output_dir, "design_spec.md")
    with open(spec_path, "w", encoding="utf-8") as f:
        f.write("\n".join(spec_lines))

    print(f"\n[+] Extraction Complete!")
    print(f"[+] Output Directory: {output_dir}")
    print(f"[+] Design Spec Markdown: {spec_path}")
    print(f"[+] Background Images: {images_dir}/ ({len(pages)} images saved)")
    return spec_path, output_dir

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: extract_sections.py <converted_html_file> [output_directory]")
        sys.exit(1)
    
    html_input = sys.argv[1]
    out_dir = sys.argv[2] if len(sys.argv) > 2 else None
    extract_sections(html_input, out_dir)
